import pty, os, sys, select, time, termios, struct, fcntl, subprocess, errno
def run_raw2(args, width=80, height=24, inputs=[], wait_after=0.5, env=None, unset_vars=[]):
    m_primary, m_replica = pty.openpty()
    fcntl.ioctl(m_replica, termios.TIOCSWINSZ, struct.pack("HHHH", height, width, 0, 0))
    e = dict(os.environ)
    if "TERM" not in e:
        e["TERM"]="xterm-256color"  # default? but if parent has TERM, keep it? Actually we want to test unset, so allow unset
        pass
    # if env is not None, apply; support value None to unset?
    if env is not None:
        for k,v in env.items():
            if v is None:
                e.pop(k,None)
            else:
                e[k]=v
    for k in unset_vars:
        e.pop(k,None)
    # if TERM was originally missing and env doesn't set it, keep missing
    # Actually parent always has TERM? In our container TERM=dumb? Check env earlier: TERM not set? env showed no TERM. Wait PWD env had no TERM. But run_raw sets TERM=xterm-256color unconditionally, so parent TERM missing still gets 256.
    # For accurate test, we need to know parent TERM: currently parent has no TERM (since env shows no TERM). So e initially has no TERM. Then old code set TERM to xterm-256color always. New code only sets if missing? That's still setting. To allow unset, we must NOT set default when testing unset.
    # So we need explicit handling: if env contains TERM-> use it, if unset_vars contains TERM -> unset, else keep parent's (which is unset -> stays unset)
    # But our e already handled: we didn't force TERM. So if parent has no TERM and env doesn't have TERM, e stays without TERM -> correct for unset test.
    # However for normal tests we need to force TERM; caller must pass TERM explicitly.
    p = subprocess.Popen(args, stdin=m_replica, stdout=m_replica, stderr=m_replica, env=e, close_fds=True)
    os.close(m_replica)
    flags = fcntl.fcntl(m_primary, fcntl.F_GETFL)
    fcntl.fcntl(m_primary, fcntl.F_SETFL, flags | os.O_NONBLOCK)
    out = b""
    def drain(timeout=0.3):
        nonlocal out
        end = time.time()+timeout
        while time.time()<end:
            try:
                r,_,_ = select.select([m_primary], [], [], 0.1)
                if r:
                    try:
                        data = os.read(m_primary, 65536)
                        if not data: break
                        out += data
                        end = time.time()+0.2
                    except OSError as ex:
                        if ex.errno in (errno.EIO, errno.EAGAIN): break
                        raise
            except Exception as ex:
                break
        return out
    drain(0.8)
    for item in inputs:
        if isinstance(item, tuple):
            data, delay = item
        else:
            data, delay = item, 0.3
        if isinstance(data, str): data = data.encode()
        time.sleep(0.1)
        os.write(m_primary, data)
        drain(delay if delay else 0.4)
    time.sleep(wait_after)
    drain(0.3)
    alive = p.poll() is None
    try:
        p.terminate()
        try: p.wait(timeout=1)
        except: p.kill()
    except: pass
    try: os.close(m_primary)
    except: pass
    return out, p.returncode
PY
