import pty, os, select, time, termios, struct, fcntl, subprocess, tempfile
def test_bytes(data):
    d=tempfile.mkdtemp()
    p=os.path.join(d,"f.txt")
    open(p,'wb').write(data)
    m_primary, m_replica = pty.openpty()
    fcntl.ioctl(m_replica, termios.TIOCSWINSZ, struct.pack("HHHH", 24,80,0,0))
    base={"PATH":os.environ.get("PATH","/usr/bin:/bin"), "TERM":"xterm-256color"}
    proc=subprocess.Popen(["./executable", p], stdin=m_replica, stdout=m_replica, stderr=m_replica, env=base)
    os.close(m_replica)
    flags=fcntl.fcntl(m_primary, fcntl.F_GETFL)
    fcntl.fcntl(m_primary, fcntl.F_SETFL, flags|os.O_NONBLOCK)
    def drain(t):
        out=b""
        end=time.time()+t
        while time.time()<end:
            r,_,_=select.select([m_primary],[],[],0.1)
            if r:
                try:
                    dd=os.read(m_primary,65536)
                    if not dd: break
                    out+=dd
                    end=time.time()+0.2
                except: break
        return out
    out=drain(1.0)
    code=proc.poll()
    if code is None:
        proc.terminate()
        try: proc.wait(timeout=1)
        except: proc.kill()
        code="alive"
    os.close(m_primary)
    if b"Error:" in out:
        # extract error line
        import re
        m=re.search(rb'Error: (.*?)\r\n', out)
        return m.group(1).decode() if m else repr(out[:200])
    else:
        return "OK"

for i in range(0x00, 0x20):
    msg=test_bytes(bytes([i])+b"a")
    print(f"0x{i:02x} -> {msg}")
for i in [0x7f, 0x80, 0x9f]:
    msg=test_bytes(bytes([i])+b"a" if i<0x80 else b"\xc2\x80")
    print(f"0x{i:02x} -> {msg}")
# test DEL, etc.
for c in [0x0b, 0x0c, 0x0e, 0x0f, 0x10, 0x1a]:
    print(f"0x{c:02x} -> {test_bytes(bytes([c]))}")
