use std::env;
use std::io::{self, Write};
use std::process::ExitCode;

const VERSION: &str = "0.4.3";

fn print_help(prog: &str) {
    // Exact help text, with prog substituted
    let mut out = String::new();
    out.push_str(&format!("{}: A tiny UTF-8 terminal text editor\n", prog));
    out.push_str("\n");
    out.push_str("Kiro is a tiny UTF-8 text editor on terminals for Unix-like systems.\n");
    out.push_str("Specify file paths to edit as a command argument or run without argument to\n");
    out.push_str("start to write a new text.\n");
    out.push_str("Help can show up with key mapping Ctrl-?.\n");
    out.push_str("\n");
    out.push_str("Usage:\n");
    out.push_str(&format!("    {} [options] [FILES...]\n", prog));
    out.push_str("\n");
    out.push_str("Mappings:\n");
    out.push_str("    Ctrl-Q                        : Quit\n");
    out.push_str("    Ctrl-S                        : Save to file\n");
    out.push_str("    Ctrl-O                        : Open text buffer\n");
    out.push_str("    Ctrl-X                        : Next text buffer\n");
    out.push_str("    Alt-X                         : Previous text buffer\n");
    out.push_str("    Ctrl-P or UP                  : Move cursor up\n");
    out.push_str("    Ctrl-N or DOWN                : Move cursor down\n");
    out.push_str("    Ctrl-F or RIGHT               : Move cursor right\n");
    out.push_str("    Ctrl-B or LEFT                : Move cursor left\n");
    out.push_str("    Ctrl-A or Alt-LEFT or HOME    : Move cursor to head of line\n");
    out.push_str("    Ctrl-E or Alt-RIGHT or END    : Move cursor to end of line\n");
    out.push_str("    Ctrl-[ or Ctrl-V or PAGE DOWN : Next page\n");
    out.push_str("    Ctrl-] or Alt-V or PAGE UP    : Previous page\n");
    out.push_str("    Alt-F or Ctrl-RIGHT           : Move cursor to next word\n");
    out.push_str("    Alt-B or Ctrl-LEFT            : Move cursor to previous word\n");
    out.push_str("    Alt-N or Ctrl-DOWN            : Move cursor to next paragraph\n");
    out.push_str("    Alt-P or Ctrl-UP              : Move cursor to previous paragraph\n");
    out.push_str("    Alt-<                         : Move cursor to top of file\n");
    out.push_str("    Alt->                         : Move cursor to bottom of file\n");
    out.push_str("    Ctrl-H or BACKSPACE           : Delete character\n");
    out.push_str("    Ctrl-D or DELETE              : Delete next character\n");
    out.push_str("    Ctrl-W                        : Delete a word\n");
    out.push_str("    Ctrl-J                        : Delete until head of line\n");
    out.push_str("    Ctrl-K                        : Delete until end of line\n");
    out.push_str("    Ctrl-U                        : Undo last change\n");
    out.push_str("    Ctrl-R                        : Redo last undo change\n");
    out.push_str("    Ctrl-G                        : Search text\n");
    out.push_str("    Ctrl-M                        : New line\n");
    out.push_str("    Ctrl-L                        : Refresh screen\n");
    out.push_str("    Ctrl-?                        : Show this help\n");
    out.push_str("\n");
    out.push_str("Options:\n");
    out.push_str("    -v, --version       Print version\n");
    out.push_str("    -h, --help          Print this help\n");
    out.push_str("\n");
    let stdout = io::stdout();
    let mut h = stdout.lock();
    let _ = h.write_all(out.as_bytes());
}

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    let prog = args.get(0).map(|s| s.as_str()).unwrap_or("kiro");
    // Parse options
    // Collect errors for U/T, and counts for help/version
    let mut help_count = 0;
    let mut version_count = 0;
    // For earliest U/T error: store (index, kind, message)
    // kind: 0=U, 1=T ; message already formatted
    let mut first_ut_error: Option<(usize, String)> = None;
    // To track order, iterate args after prog
    let mut files: Vec<String> = Vec::new();
    let mut seen_dashdash = false;
    // For duplicate detection, need counts; but also need to handle short clusters
    // We'll first scan to collect U/T errors and counts
    // Position index for ordering: use arg position (0-based among args[1..])
    let mut arg_idx = 0usize;
    // We'll need to handle each arg in order
    // Store per-arg errors? Actually first U/T is earliest in arg order, and within short cluster, earliest char?
    // For long with =, only one error per arg. For short cluster, first unknown char in cluster is error for that arg.
    // For T errors, they are per long arg.
    // So we can iterate and record first.
    let mut i = 1;
    while i < args.len() {
        let a = &args[i];
        if seen_dashdash {
            files.push(a.clone());
            i += 1;
            arg_idx += 1;
            continue;
        }
        if a == "--" {
            seen_dashdash = true;
            i += 1;
            arg_idx += 1;
            continue;
        }
        if a == "-" {
            files.push(a.clone());
            i += 1;
            arg_idx += 1;
            continue;
        }
        if a.starts_with("--") {
            // long option
            let rest = &a[2..];
            // split at first '='
            let (name, has_eq) = match rest.find('=') {
                Some(pos) => (&rest[..pos], true),
                None => (rest, false),
            };
            let is_help = name == "h" || name == "help";
            let is_version = name == "v" || name == "version";
            if is_help || is_version {
