#[derive(Clone, Copy, PartialEq)]
enum ColorMode { C16, C256, True }

fn detect_color_mode() -> ColorMode {
    if let Ok(v) = env::var("COLORTERM") {
        if v == "truecolor" {
            return ColorMode::True;
        }
    }
    let term = env::var("TERM").unwrap_or_default();
    if term.is_empty() {
        return ColorMode::C16;
    }
    // try terminfo
    if let Some(n) = terminfo_colors(&term) {
        if n >= 256 {
            return ColorMode::C256;
        } else {
            return ColorMode::C16;
        }
    }
    ColorMode::C16
}

fn terminfo_colors(term: &str) -> Option<i32> {
    // search paths
    let mut dirs: Vec<String> = Vec::new();
    if let Ok(v) = env::var("TERMINFO") {
        if !v.is_empty() { dirs.push(v); }
    }
    if let Ok(home) = env::var("HOME") {
        if !home.is_empty() { dirs.push(format!("{}/.terminfo", home)); }
    }
    if let Ok(v) = env::var("TERMINFO_DIRS") {
        for p in v.split(':') {
            if p.is_empty() {
                // default dirs
                dirs.push("/etc/terminfo".to_string());
                dirs.push("/lib/terminfo".to_string());
                dirs.push("/usr/share/terminfo".to_string());
            } else {
                dirs.push(p.to_string());
            }
        }
    } else {
        dirs.push("/etc/terminfo".to_string());
        dirs.push("/lib/terminfo".to_string());
        dirs.push("/usr/share/terminfo".to_string());
        dirs.push("/usr/share/lib/terminfo".to_string());
    }
    // also try /lib/terminfo etc. (already)
    for d in dirs {
        if d.is_empty() { continue; }
        let first = term.chars().next().unwrap();
        // terminfo uses first char as subdir; for safety, use first byte?
        let path = format!("{}/{}/{}", d, first, term);
        if let Some(n) = parse_terminfo_colors(&path) {
            return Some(n);
        }
    }
    None
}

fn parse_terminfo_colors(path: &str) -> Option<i32> {
    let data = fs::read(path).ok()?;
    if data.len() < 12 { return None; }
    let magic = u16::from_le_bytes([data[0], data[1]]);
    let is_extended;
    if magic == 0x011A {
        is_extended = false;
    } else if magic == 0x021E {
        is_extended = true;
    } else {
        return None;
    }
    let names_size = u16::from_le_bytes([data[2], data[3]]) as usize;
    let bool_count = u16::from_le_bytes([data[4], data[5]]) as usize;
    let num_count = u16::from_le_bytes([data[6], data[7]]) as usize;
    //let str_count = u16::from_le_bytes([data[8], data[9]]) as usize;
    //let table_size = u16::from_le_bytes([data[10], data[11]]) as usize;
    if num_count <= 13 {
        return None;
    }
    let mut off = 12 + names_size;
    // after names, bool section
    off += bool_count;
    // pad to even
    if (12 + names_size + bool_count) % 2 != 0 {
        off += 1;
    }
    // numbers: u16 each, or u32 if extended and ... Actually extended still uses u16 for numbers? No, 0x021E uses u32? Let's handle both: if is_extended, numbers are u32? Actually spec: magic 542 (0x021E) indicates 32-bit numbers? No, need to check: terminfo with magic 542 has 32-bit numbers? Hmm.
    // Simpler: try u16 first, if fails, try u32.
    // For 256color files, they are old format (0x011A) with u16 numbers, so easy.
    if !is_extended {
        if off + num_count*2 > data.len() { return None; }
        let mut nums = Vec::new();
        for i in 0..num_count {
            let v = u16::from_le_bytes([data[off+i*2], data[off+i*2+1]]) as i16 as i32;
            nums.push(v);
        }
        // max_colors is index 13
        let c = nums[13];
        if c < 0 { return None; }
        return Some(c);
    } else {
        // extended: numbers are u32? Actually header same but numbers are 32-bit? Let's parse as u32
        // After bool + pad to even? For extended, pad to 4? Hmm.
        // Simplify: return None -> fallback to 16 (should not happen for our terms, which are old format)
        return None;
    }
}

