fn char_width(c: char) -> usize {
    if c == '\0' { return 1; }
    if c == '\t' { return 0; } // handled separately
    let o = c as u32;
    if o < 32 || o == 127 { return 0; }
    // combining
    if (0x0300..=0x036F).contains(&o) || (0x1AB0..=0x1AFF).contains(&o) || (0x1DC0..=0x1DFF).contains(&o)
        || (0x20D0..=0x20FF).contains(&o) || (0xFE20..=0xFE2F).contains(&o) { return 0; }
    // wide
    if (0x1100..=0x115F).contains(&o) || o==0x2329 || o==0x232A || (0x2E80..=0x303E).contains(&o)
        || (0x3041..=0x33FF).contains(&o) || (0x3400..=0x4DBF).contains(&o) || (0x4E00..=0xA4CF).contains(&o)
        || (0xA960..=0xA97C).contains(&o) || (0xAC00..=0xD7A3).contains(&o) || (0xF900..=0xFAFF).contains(&o)
        || (0xFE10..=0xFE19).contains(&o) || (0xFE30..=0xFE52).contains(&o) || (0xFE54..=0xFE66).contains(&o)
        || (0xFE68..=0xFE6B).contains(&o) || (0xFF00..=0xFF60).contains(&o) || (0xFFE0..=0xFFE6).contains(&o)
        || (0x20000..=0x3FFFD).contains(&o) { return 2; }
    1
}

