// ============ Row ============
#[derive(Clone)]
struct Row {
    chars: Vec<char>, // original chars
    render: String,   // rendered with tabs expanded (as String)
    render_chars: Vec<char>, // render as chars for width handling? Actually render String's chars
    hl: Vec<Hl>, // per render char? We'll store per render char index (char-based, not byte)
    hl_open_comment: bool, // whether this row ends inside multi-comment? For next row
}

impl Row {
    fn new(s: &str) -> Row {
        Row { chars: s.chars().collect(), render: String::new(), render_chars: Vec::new(), hl: Vec::new(), hl_open_comment: false }
    }
    fn update_render(&mut self) {
        let mut r = String::new();
        for c in &self.chars {
            if *c == '\t' {
                let cur_len = display_width_str(&r);
                let spaces = TAB_STOP - (cur_len % TAB_STOP);
                for _ in 0..spaces { r.push(' '); }
            } else if *c == '\0' {
                r.push('\0');
            } else {
                r.push(*c);
            }
        }
        self.render = r;
        self.render_chars = self.render.chars().collect();
    }
}

fn display_width_str(s: &str) -> usize {
    let mut w = 0;
    for c in s.chars() {
        if c == '\t' { w += TAB_STOP - (w % TAB_STOP); }
        else { w += char_width(c); }
    }
    w
}
fn display_width_chars(cs: &[char]) -> usize {
    let mut w = 0;
    for &c in cs {
        if c == '\t' { w += TAB_STOP - (w % TAB_STOP); }
        else { w += char_width(c); }
    }
    w
}

// highlight a row given filetype and whether previous row ends in comment
fn highlight_row(ft: FileType, row: &mut Row, prev_open: bool) -> bool {
    // returns whether this row ends open (for next)
    let chars: Vec<char> = row.render_chars.clone();
    let n = chars.len();
    let mut hl = vec![Hl::Normal; n];
    let sc = single_comment(ft);
    let mc = multi_comment(ft);
    let has_str = has_strings(ft);
    let mut in_string: Option<char> = None; // '"' or '\'' or '`' (for go)
    let mut in_comment_multi = prev_open;
    let mut i = 0;
    // For char literal handling in C-like: need to detect '\'' correctly
    // We'll handle strings first, with special char logic
    while i < n {
        let c = chars[i];
        // if in multi-comment
        if in_comment_multi {
            hl[i] = Hl::Comment;
            // check for end
            if let Some((_, end)) = mc {
                let end_chars: Vec<char> = end.chars().collect();
                if i + end_chars.len() <= n && chars[i..i+end_chars.len()].iter().collect::<String>() == end {
                    for k in 0..end_chars.len() { hl[i+k] = Hl::Comment; }
                    i += end_chars.len();
                    in_comment_multi = false;
                    continue;
                }
            }
            i += 1;
            continue;
        }
        // if in string
        if let Some(q) = in_string {
            hl[i] = Hl::String;
            if c == '\\' && i+1 < n {
                // escape next
                hl[i+1] = Hl::String;
                i += 2;
                continue;
            }
            if c == q {
                // For single-quote char in Rust/C/Go: need to validate char literal length?
                // We'll handle after: if q=='\'' and ft is Rust/C/Cpp/Go, only highlight if valid char literal
                // For now, close string
                in_string = None;
            }
            i += 1;
            continue;
        }
        // check for multi-comment start (if not in string)
        if let Some((start, _)) = mc {
            let s_chars: Vec<char> = start.chars().collect();
            if i + s_chars.len() <= n && chars[i..i+s_chars.len()].iter().collect::<String>() == start {
                // check that it's not inside string (we already are not in string)
                for k in 0..s_chars.len() { hl[i+k] = Hl::Comment; }
                i += s_chars.len();
                in_comment_multi = true;
                continue;
            }
        }
