// ============ Terminal raw mode ============
#[repr(C)]
struct WinSize { row: u16, col: u16, x: u16, y: u16 }

extern "C" {
    fn tcgetattr(fd: i32, termios_p: *mut u8) -> i32;
    fn tcsetattr(fd: i32, opt: i32, termios_p: *const u8) -> i32;
    fn ioctl(fd: i32, req: u64, ...) -> i32;
    fn read(fd: i32, buf: *mut u8, count: usize) -> isize;
    fn write(fd: i32, buf: *const u8, count: usize) -> isize;
}

const TCGETS: u64 = 0x5401;
const TCSETS: u64 = 0x5402;
const TCSAFLUSH: i32 = 2;
const TIOCGWINSZ: u64 = 0x5413;

fn get_winsize() -> Option<(usize, usize)> {
    unsafe {
        let mut ws = WinSize{row:0,col:0,x:0,y:0};
        let r = ioctl(1, TIOCGWINSZ, &mut ws as *mut WinSize);
        if r != 0 {
            // try stdin/stdout/stderr?
            let r2 = ioctl(0, TIOCGWINSZ, &mut ws as *mut WinSize);
            if r2 != 0 { return None; }
        }
        if ws.col==0 || ws.row==0 { return None; }
        Some((ws.col as usize, ws.row as usize))
    }
}

struct RawGuard { orig: Vec<u8> }
impl RawGuard {
    fn enable() -> io::Result<RawGuard> {
        unsafe {
            let mut orig = vec![0u8; 64];
            if tcgetattr(0, orig.as_mut_ptr()) != 0 {
                return Err(io::Error::last_os_error());
            }
            let mut raw = orig.clone();
            // raw mode: clear flags
            // termios layout: c_iflag at 0, c_oflag at 4, c_cflag at 8, c_lflag at 12, c_line at 16, c_cc[32] at 17..49, ispeed at 52?, ospeed at 56? (with padding)
            // For simplicity, manipulate via known offsets (Linux x86_64):
            // Use u32 reads
            let iflag = u32::from_ne_bytes([raw[0],raw[1],raw[2],raw[3]]);
            let oflag = u32::from_ne_bytes([raw[4],raw[5],raw[6],raw[7]]);
            let cflag = u32::from_ne_bytes([raw[8],raw[9],raw[10],raw[11]]);
            let lflag = u32::from_ne_bytes([raw[12],raw[13],raw[14],raw[15]]);
            // BRKINT=0x0002, ICRNL=0x0100, INPCK=0x0010, ISTRIP=0x0020, IXON=0x0400
            let niflag = iflag & !(0x0002 | 0x0100 | 0x0010 | 0x0020 | 0x0400);
            // OPOST=0x0001
            let noflag = oflag & !(0x0001);
            // CS8=0x0030, need to set CS8 (clear CSIZE 0x0030? Actually CSIZE=0x0030, CS8=0x0030, so set)
            let ncflag = (cflag & !(0x0030)) | 0x0030;
            // ECHO=0x0008, ICANON=0x0002, IEXTEN=0x8000, ISIG=0x0001
            let nlflag = lflag & !(0x0008 | 0x0002 | 0x8000 | 0x0001);
            raw[0..4].copy_from_slice(&niflag.to_ne_bytes());
            raw[4..8].copy_from_slice(&noflag.to_ne_bytes());
            raw[8..12].copy_from_slice(&ncflag.to_ne_bytes());
            raw[12..16].copy_from_slice(&nlflag.to_ne_bytes());
            // VMIN=6, VTIME=5 indices in c_cc (starting at offset 17)
            // c_cc[VMIN]=1, c_cc[VTIME]=0
            raw[17+6] = 1;
            raw[17+5] = 0;
            if tcsetattr(0, TCSAFLUSH, raw.as_ptr()) != 0 {
                return Err(io::Error::last_os_error());
            }
            Ok(RawGuard{orig})
        }
    }
}
impl Drop for RawGuard {
    fn drop(&mut self) {
        unsafe { let _ = tcsetattr(0, TCSAFLUSH, self.orig.as_ptr()); }
    }
}

fn write_all(fd: i32, mut buf: &[u8]) {
    unsafe {
        while !buf.is_empty() {
            let n = write(fd, buf.as_ptr(), buf.len());
            if n <= 0 { break; }
            buf = &buf[(n as usize)..];
        }
    }
}
fn read_byte() -> Option<u8> {
    unsafe {
        let mut b = [0u8;1];
        let n = read(0, b.as_mut_ptr(), 1);
        if n == 1 { Some(b[0]) } else { None }
    }
}

